  window.PFAPatronCard = { CARD: CARD, attach: attach, attachAll: attachAll, readState: readState, draw: draw, hydrate: hydrate, offscreen: offscreen, downloadPdf: downloadPdf, downloadPng: downloadPng };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { attachAll(); });
